import math
import numpy as np
import pandas as pd
from sklearn.cluster import DBSCAN
from joblib import Parallel, delayed

CITSCI_PATH = "/root/data/citsci_train.csv"
EXPERT_PATH = "/root/data/expert_train.csv"
OUT_PATH = "/root/pareto_frontier.csv"

MAX_MATCH_DIST = 100.0


def load_data():
    citsci = pd.read_csv(CITSCI_PATH, usecols=["file_rad", "x", "y"])
    expert = pd.read_csv(EXPERT_PATH, usecols=["file_rad", "x", "y"])
    images = expert["file_rad"].unique().tolist()

    citsci_groups = {
        k: v[["x", "y"]].to_numpy(dtype=float)
        for k, v in citsci.groupby("file_rad")
    }
    expert_groups = {
        k: v[["x", "y"]].to_numpy(dtype=float)
        for k, v in expert.groupby("file_rad")
    }

    image_data = []
    for img in images:
        cs_arr = citsci_groups.get(img)
        if cs_arr is None:
            cs_arr = np.empty((0, 2), dtype=float)
        ex_arr = expert_groups.get(img)
        if ex_arr is None:
            ex_arr = np.empty((0, 2), dtype=float)
        image_data.append((cs_arr, ex_arr))

    return image_data


def make_metric(weight):
    w = float(weight)
    wy = 2.0 - w

    def metric(a, b):
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return math.sqrt((w * dx) ** 2 + (wy * dy) ** 2)

    return metric


def greedy_match(centroids, experts):
    if centroids.size == 0 or experts.size == 0:
        return []

    diffs = centroids[:, None, :] - experts[None, :, :]
    dist = np.sqrt(np.sum(diffs * diffs, axis=2))
    dist[dist > MAX_MATCH_DIST] = np.inf

    matches = []
    while True:
        flat_idx = np.argmin(dist)
        min_val = dist.flat[flat_idx]
        if not np.isfinite(min_val):
            break
        c_idx, e_idx = np.unravel_index(flat_idx, dist.shape)
        matches.append(min_val)
        dist[c_idx, :] = np.inf
        dist[:, e_idx] = np.inf

    return matches


def evaluate_image(cs_arr, ex_arr, min_samples, eps, weight):
    if cs_arr.shape[0] == 0:
        return 0.0, float("nan")

    metric = make_metric(weight)
    db = DBSCAN(
        eps=eps,
        min_samples=min_samples,
        metric=metric,
        algorithm="brute",
        n_jobs=1,
    )
    labels = db.fit_predict(cs_arr)
    cluster_ids = [cid for cid in set(labels.tolist()) if cid != -1]
    if not cluster_ids:
        return 0.0, float("nan")

    centroids = []
    for cid in cluster_ids:
        pts = cs_arr[labels == cid]
        if pts.size == 0:
            continue
        centroids.append(pts.mean(axis=0))
    if not centroids:
        return 0.0, float("nan")

    centroids = np.vstack(centroids)
    matches = greedy_match(centroids, ex_arr)
    tp = len(matches)
    if tp == 0:
        return 0.0, float("nan")

    fp = centroids.shape[0] - tp
    fn = ex_arr.shape[0] - tp
    f1 = 2.0 * tp / (2.0 * tp + fp + fn)
    delta = float(np.mean(matches))
    return f1, delta


def evaluate_combo(image_data, min_samples, eps, weight):
    f1s = []
    deltas = []
    for cs_arr, ex_arr in image_data:
        f1, delta = evaluate_image(cs_arr, ex_arr, min_samples, eps, weight)
        f1s.append(f1)
        if not math.isnan(delta):
            deltas.append(delta)

    avg_f1 = float(np.mean(f1s)) if f1s else 0.0
    avg_delta = float(np.mean(deltas)) if deltas else float("nan")
    return {
        "F1": avg_f1,
        "delta": avg_delta,
        "min_samples": int(min_samples),
        "epsilon": int(eps),
        "shape_weight": float(weight),
    }


def pareto_frontier(results):
    frontier = []
    for i, r1 in enumerate(results):
        dominated = False
        for j, r2 in enumerate(results):
            if i == j:
                continue
            if (
                r2["F1"] >= r1["F1"]
                and r2["delta"] <= r1["delta"]
                and (r2["F1"] > r1["F1"] or r2["delta"] < r1["delta"])
            ):
                dominated = True
                break
        if not dominated:
            frontier.append(r1)
    return frontier


def main():
    image_data = load_data()

    min_samples_grid = list(range(3, 10))
    eps_grid = list(range(4, 25, 2))
    weight_grid = [round(0.9 + 0.1 * i, 1) for i in range(11)]

    combos = [
        (min_samples, eps, weight)
        for min_samples in min_samples_grid
        for eps in eps_grid
        for weight in weight_grid
    ]

    results = Parallel(n_jobs=-1, prefer="processes")(
        delayed(evaluate_combo)(image_data, min_samples, eps, weight)
        for min_samples, eps, weight in combos
    )

    filtered = [
        r
        for r in results
        if r["F1"] > 0.5 and not math.isnan(r["delta"])
    ]

    frontier = pareto_frontier(filtered)
    frontier.sort(key=lambda r: (-r["F1"], r["delta"]))

    if frontier:
        df = pd.DataFrame(frontier)
        df["F1"] = df["F1"].round(5)
        df["delta"] = df["delta"].round(5)
        df["shape_weight"] = df["shape_weight"].round(1)
        df = df[["F1", "delta", "min_samples", "epsilon", "shape_weight"]]
        df.to_csv(OUT_PATH, index=False)
    else:
        pd.DataFrame(
            columns=["F1", "delta", "min_samples", "epsilon", "shape_weight"]
        ).to_csv(OUT_PATH, index=False)


if __name__ == "__main__":
    main()
